7 - تحديد طريقة تخزين البيانات الشخصية .
8 - بيان آلية الحصول على موافقة الشخص المعنى بالبيانات وتسجيلها .
9 - استيفاء كافة البيانات الفنية عن البنية التحتية المستخدمة ومنها (أنواع الأجهزة المستخدمة - الشهادات والاعتمادات الفنية الحالية) ، ومدى مطابقتها للاشتراطات والالتزامات الفنية والتشغيلية الواجب توافرها والتى يحددها المركز .
10 - تقديم الشهادات والاعتمادات الفنية التى حصل عليها طالب التصريح فى شأن تأمين الاحتفاظ بالبيانات الشخصية ومعالجتها ، مع تحديد الجهات المانحة لها ، وتاريخ الحصول عليها ومدة صلاحيتها .$m232$,'a4073e31ec3b27e0517585fdd8adcdf7',DATE '2025-11-02',NULL,'active',NULL,NULL,NULL),
(38,0,1,$m232$يصدر المركز التصاريح للأشخاص الطبيعية من خلال بوابة إلكترونية تنشأ بغرض تلقى الطلبات الخاصة باستخراج التصاريح للأشخاص الطبيعية ، وفقا للإجراءات الآتية :
1 - يقدم طلب الحصول على أى من فئات التصاريح المحددة بهذه اللائحة إلى المركز من خلال البوابة الإلكترونية المخصصة لذلك ، على أن يشتمل الطلب على جميع البيانات والمستندات المبينة بهذه اللائحة لكل فئة من فئات التصاريح واستيفاء الاشتراطات الأخرى التى يحددها المركز .
2 - يتولى المركز دراسة الطلب من خلال فرق العمل المتخصصة ، وفقا للإجراءات والقواعد المقررة ، وله التواصل مع مقدم الطلب حال الحاجة إلى استيضاح أى نقاط أو استيفاء أى مستندات لازمة للبت فى الطلب .
3 - يقوم المركز بإبلاغ مقدم الطلب بما انتهت إليه الدراسة سواء بالموافقة أو الرفض وذلك خلال مدة لا تجاوز 90 يوم من تاريخ استيفائه لجميع البيانات والمستندات ، ويعد عدم الرد بمثابة رفض للطلب .
وفى حالة قبول المركز الطلب يكون التصريح للشخص الطبيعى لمدة لا تجاوز عام ، ويكون هو المسئول عن تطبيق أحكام القانون والقائم بأعمال مسئول حماية البيانات .$m232$,'008747af70385e25e2230bb3e5add227',DATE '2025-11-02',NULL,'active',NULL,NULL,NULL),
(39,0,1,$m232$• تلتزم كل من الجمعيات والنقابات والنوادى ، حال تعاملها على البيانات الشخصية الخاصة بأعضائها وفى إطار أنشطتها ، بالحصول على التراخيص/ التصاريح اللازمة لذلك وفقا للضوابط والشروط المبينة بالقانون وهذه اللائحة .
• وفى حالة زيادة أعداد سجلات البيانات الشخصية الصادر عنها الترخيص أو التصريح فيتعين على الأشخاص الطبيعية والاعتبارية التقدم للمركز لتعديل الترخيص/ التصريح طبقا لطبيعة وحجم البيانات وفئاتها .
• وتلتزم الأشخاص الاعتبارية الراغبة فى الحصول على تراخيص أو تصاريح وفقا لأحكام القانون وهذه اللائحة بالحصول على الموافقات اللازمة لمزاولة نشاطها .$m232$,'d07f20ae622eb35fa76c524d7b2d8cef',DATE '2025-11-02',NULL,'active',NULL,NULL,NULL),
(40,0,1,$m232$أولا - تجديد التراخيص :
ينتهى الترخيص بانتهاء مدته ، ويجوز تجديده لمدد أخرى بموجب طلب يتقدم به المرخص له إلى المركز وفق الآليات التى يحددها ، وذلك قبل نهاية مدة الترخيص بثلاثة أشهر على الأقل .
ويكون التجديد وفقا للضوابط والشروط وبعد سداد الرسوم المقررة لإصدار الترخيص .
ثانيا - تجديد التصاريح :
ينتهى التصريح بانتهاء مدته ، ويجوز تجديده لأكثر من مرة بموجب طلب يتقدم به المصرح له إلى المركز وفق الآليات التى يحددها ، وذلك قبل نهاية مدة التصريح بشهر على الأقل .
ويكون التجديد وفقا للضوابط والشروط وبعد سداد الرسوم المقررة لإصدار التصريح .$m232$,'e9abb082e491074d26eb905c31942fc4',DATE '2025-11-02',NULL,'active',NULL,NULL,NULL),
(41,0,1,$m232$تعد النماذج الخاصة بالتقدم للحصول على التراخيص/ التصاريح/ الاعتمادات فى صورة الكترونية تقدم عبر منصة تفاعلية من خلال البوابة الإلكترونية للمركز .
ويحدد نوع النموذج والشروط والضوابط والإجراءات اللازمة للحصول على التراخيص/ التصاريح / الاعتمادات فى ضوء طبيعة نشاط المتقدم ، والبيانات التى يقوم باختيارها من المحتوى المسجل على المنصة والمتضمن كافة الشرائح والفئات والمستويات الخاصة بحجم البيانات الشخصية وطبيعتها وأساليب حفظها وتأمينها والغرض منها وغيرها من المعايير والضوابط والتدابير الأخرى التى يرى مجلس إدارة المركز اعتمادها لحماية البيانات الشخصية .
ويصدر النموذج إلكترونيا بعد مراجعة المتطلبات والمستندات والبيانات اللازمة لإصداره ، ومنها الآتى :
1 - بيان نوع البيانات الشخصية ، والغرض من الاحتفاظ بها أو معالجتها .
2 - بيان بالمدد الزمنية للاحتفاظ بالبيانات الشخصية ، والتزام المرخص/ المصرح له بمحو هذه البيانات فور انقضاء الغرض المحدد منها .
3 - ما يفيد إمساكه سجل خاص للبيانات الشخصية يتضمن فئاتها ، وتحديد من سيفصح أو يتيح لهم تلك البيانات ، وسند ذلك ، وآليات محوها لديه أو تعديلها ، وكذا أى بيانات أخرى متعلقة بنقل البيانات الشخصية عبر الحدود .
4 - بيان بآلية الحصول على موافقة الشخص المعنى بالبيانات .
5 - إقرار بالالتزامات الخاصة بأمن البيانات الشخصية .
6 - إقرار بتوفير الإمكانيات اللازمة بما يمكن المركز من التفتيش والرقابة .
7 - إقرار المتعاملين مع المرخص له بضمان سرية البيانات الشخصية .
8 - إقرار بالوفاء بالجزاءات المالية والتعويضات التى يقرها المركز .$m232$,'c1db81585c8ee19cd591c7357572d0be',DATE '2025-11-02',NULL,'active',NULL,NULL,NULL);

DO $m232$
DECLARE
  v_law uuid;
  v_title text;
  v_new_law boolean := false;
  v_ins_art int;
  v_ins_ver int;
  v_cnt int;
  v_vcnt int;
BEGIN
  IF (SELECT count(*) FROM m232_art WHERE md5(body) <> body_md5) <> 0 OR (SELECT count(*) FROM m232_ver WHERE md5(body) <> body_md5) <> 0 THEN
    RAISE EXCEPTION '[232] تلف فى نص أحد الصفوف داخل الملف';
  END IF;
  IF (SELECT count(*) FROM m232_art) <> 44 OR (SELECT sum(char_length(body)) FROM m232_art) <> 46058 OR (SELECT count(*) FROM m232_ver) <> 44 THEN
    RAISE EXCEPTION '[232] عدد الصفوف أو النسخ أو طول النص داخل الملف غير مطابق';
  END IF;

  SELECT id, title INTO v_law, v_title FROM laws WHERE country_code='EG' AND law_no=816 AND law_year=2025 AND kind='regulation';
  IF v_law IS NOT NULL AND v_title NOT LIKE '%حماية البيانات الشخصية%' THEN
    RAISE EXCEPTION '[232] يوجد مستند آخر برقم 816 لسنة 2025 (%): لا يُدمج هذا النص فيه', v_title;
  END IF;
  IF v_law IS NULL THEN
    INSERT INTO laws (law_no, law_year, title, short_title, category, status, official_url, enacted_at, last_amended_at, country_code, kind, governance_scope)
    VALUES (816, 2025, $t232$اللائحة التنفيذية لقانون حماية البيانات الشخصية الصادر بالقانون رقم 151 لسنة 2020 بقرار وزير الاتصالات وتكنولوجيا المعلومات رقم 816 لسنة 2025$t232$, $t232$اللائحة التنفيذية لقانون حماية البيانات الشخصية 816/2025$t232$, 'other', 'in_force', NULL, DATE '2025-11-01', NULL, 'EG', 'regulation', false)
    RETURNING id INTO v_law;
    v_new_law := true;
  END IF;

  INSERT INTO articles (law_id, article_no, article_suffix_order, hierarchical_location, body)
  SELECT v_law, article_no, suffix, loc, body FROM m232_art
  ON CONFLICT (law_id, article_no, article_suffix_order) DO NOTHING;
  GET DIAGNOSTICS v_ins_art = ROW_COUNT;

  INSERT INTO article_versions (article_id, version_no, body, effective_from, effective_to, status, amended_by_law_no, amended_by_law_year, change_note)
  SELECT a.id, m.version_no, m.body, m.eff, m.eff_to, m.status, m.am_no, m.am_yr, m.note
    FROM articles a JOIN m232_ver m ON m.article_no = a.article_no AND m.suffix = a.article_suffix_order
   WHERE a.law_id = v_law
     AND NOT EXISTS (SELECT 1 FROM article_versions v WHERE v.article_id = a.id)
  ON CONFLICT (article_id, version_no) DO NOTHING;
  GET DIAGNOSTICS v_ins_ver = ROW_COUNT;

  SELECT count(*) INTO v_cnt FROM articles a JOIN m232_art m ON m.article_no=a.article_no AND m.suffix=a.article_suffix_order
   WHERE a.law_id=v_law;
  IF v_cnt <> 44 THEN
    RAISE EXCEPTION '[232] عدد صفوف النص % بدل 44', v_cnt;
  END IF;
  SELECT count(*) INTO v_vcnt FROM article_versions v JOIN articles a ON a.id=v.article_id WHERE a.law_id=v_law;
  IF v_vcnt <> 44 THEN
    RAISE EXCEPTION '[232] عدد نسخ النص % بدل 44', v_vcnt;
  END IF;
  RAISE NOTICE '[232] لائحة 816/2025: جديد=%، صفوف مضافة=%، نسخ مضافة=%', v_new_law, v_ins_art, v_ins_ver;
END
$m232$;
